// Generated by esquadro: do not edit. Signing in to the frontend: the
// session, the guard of its pages (which keeps the page asked for, to go back
// to it after signing in), and the roles let in.
import { isApiError } from "@api"
import type { Session } from "@api"
import { queryOptions, useQuery } from "@tanstack/react-query"
import type { QueryClient } from "@tanstack/react-query"
import { redirect } from "@tanstack/react-router"
import { api } from "../api.ts"
import { realmKey, roles } from "../config.ts"
import { announceSession } from "./connection.tsx"

const identity = () => api.identity[realmKey]

/** The session, or null when no one signed in. */
export const sessionQuery = queryOptions({
  queryKey: ["session"],
  queryFn: async (): Promise<Session | null> => {
    try {
      return await identity().session()
    } catch (e) {
      if (isApiError(e) && e.status === 401) return null
      throw e
    }
  },
  staleTime: 60_000,
})

export function useSession(): Session | null {
  return useQuery(sessionQuery).data ?? null
}

/** Whether the session has one of the roles let in. */
export function allowed(session: Session): boolean {
  return roles.length === 0 || session.roles.some((r) => roles.includes(r))
}

/**
 * The guard of the signed-in pages: without a session, the sign-in page,
 * with the page asked for kept in ?redirect; without a role let in, 403.
 */
export async function requireSession(queryClient: QueryClient, href: string): Promise<Session> {
  const session = await queryClient.ensureQueryData(sessionQuery)
  if (!session) {
    throw redirect({ to: "/login", search: { redirect: href } })
  }
  if (!allowed(session)) {
    throw redirect({ to: "/forbidden" })
  }
  return session
}

export async function signIn(queryClient: QueryClient, email: string, password: string): Promise<void> {
  const session = await identity().signIn({ email, password })
  queryClient.setQueryData(sessionQuery.queryKey, session)
  announceSession("signed-in")
}

export async function signOut(queryClient: QueryClient): Promise<void> {
  try {
    await identity().signOut()
  } finally {
    queryClient.setQueryData(sessionQuery.queryKey, null)
    queryClient.clear()
    announceSession("signed-out")
  }
}

/** Where to go after signing in: the page asked for, if it is one of ours. */
export function afterSignIn(target: unknown): string {
  return typeof target === "string" && target.startsWith("/") && !target.startsWith("//") ? target : "/"
}
